CREATE FUNCTION public.earn_credits(_action text) RETURNS public.user_wallets
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE pts int; w public.user_wallets;
BEGIN
  SELECT points INTO pts FROM public.credit_rules WHERE action = _action;
  IF pts IS NULL THEN RAISE EXCEPTION 'unknown action'; END IF;
  INSERT INTO public.wallet_transactions(user_id, action, points) VALUES (auth.uid(), _action, pts);
  UPDATE public.user_wallets SET balance = balance + pts, lifetime_earned = lifetime_earned + pts,
    tier = CASE WHEN lifetime_earned + pts >= 2500 THEN 'elite' ELSE tier END
  WHERE user_id = auth.uid() RETURNING * INTO w;
  RETURN w;
END $$;

